contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, address target) public payable {
        require(target != address(0));
        require(amount <= address(c).balance);

        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool sent;
        c.sendMoney(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { sent = false; } else { sent = true; }

        assert(!sent || (address(c).balance == balBefore - amount && c.depositsCount() == countBefore));
    }

    receive() external payable {}
}

